1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	
5	/**
6	 * First-party live-chat widget (Tidio-style). Floating bubble bottom-right that
7	 * opens a chat panel. Identifies the visitor with a persistent `visitorId` in
8	 * localStorage, posts messages to /api/chat, and polls GET /api/chat every ~4s
9	 * while open. On the very first message it optionally captures name + email.
10	 *
11	 * Mounted by the orchestrator (near <CookieConsent/> in app/layout.tsx) — it
12	 * does not mount itself anywhere.
13	 */
14	
15	type Msg = { id: string; sender: string; body: string; createdAt: string };
16	
17	const VISITOR_KEY = "nxeon_chat_visitor";
18	const POLL_MS = 4000;
19	
20	function getVisitorId(): string {
21	  try {
22	    let id = localStorage.getItem(VISITOR_KEY);
23	    if (!id) {
24	      id =
25	        typeof crypto !== "undefined" && crypto.randomUUID
26	          ? crypto.randomUUID()
27	          : `v_${Date.now()}_${Math.random().toString(36).slice(2)}`;
28	      localStorage.setItem(VISITOR_KEY, id);
29	    }
30	    return id;
31	  } catch {
32	    return `v_${Date.now()}_${Math.random().toString(36).slice(2)}`;
33	  }
34	}
35	
36	export default function ChatWidget() {
37	  const [open, setOpen] = useState(false);
38	  const [visitorId, setVisitorId] = useState("");
39	  const [messages, setMessages] = useState<Msg[]>([]);
40	  const [draft, setDraft] = useState("");
41	  const [name, setName] = useState("");
42	  const [email, setEmail] = useState("");
43	  const [sending, setSending] = useState(false);
44	  const [error, setError] = useState("");
45	  const [started, setStarted] = useState(false);
46	  const scrollRef = useRef<HTMLDivElement>(null);
47	
48	  useEffect(() => setVisitorId(getVisitorId()), []);
49	
50	  const poll = useCallback(async () => {
51	    if (!visitorId) return;
52	    try {
53	      const res = await fetch(`/api/chat?visitorId=${encodeURIComponent(visitorId)}`, {
54	        cache: "no-store",
55	      });
56	      if (!res.ok) return;
57	      const data = (await res.json()) as { conversation: unknown; messages: Msg[] };
58	      if (data.conversation) {
59	        setStarted(true);
60	        setMessages(data.messages ?? []);
61	      }
62	    } catch {
63	      /* transient network error — next poll retries */
64	    }
65	  }, [visitorId]);
66	
67	  // Poll while the panel is open.
68	  useEffect(() => {
69	    if (!open || !visitorId) return;
70	    poll();
71	    const t = setInterval(poll, POLL_MS);
72	    return () => clearInterval(t);
73	  }, [open, visitorId, poll]);
74	
75	  // Keep the transcript scrolled to the newest message.
76	  useEffect(() => {
77	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
78	  }, [messages, open]);
79	
80	  async function send() {
81	    const body = draft.trim();
82	    if (!body || sending || !visitorId) return;
83	    setSending(true);
84	    setError("");
85	    // Optimistic echo so the input feels instant.
86	    const optimistic: Msg = {
87	      id: `tmp_${Date.now()}`,
88	      sender: "visitor",
89	      body,
90	      createdAt: new Date().toISOString(),
91	    };
92	    setMessages((m) => [...m, optimistic]);
93	    setDraft("");
94	    try {
95	      const res = await fetch("/api/chat", {
96	        method: "POST",
97	        headers: { "Content-Type": "application/json" },
98	        body: JSON.stringify({
99	          visitorId,
100	          body,
101	          name: name.trim() || undefined,
102	          email: email.trim() || undefined,
103	        }),
104	      });
105	      if (!res.ok) {
106	        const j = (await res.json().catch(() => ({}))) as { error?: string };
107	        setError(j.error ?? "Could not send. Please try again.");
108	        return;
109	      }
110	      const data = (await res.json()) as { messages: Msg[] };
111	      setStarted(true);
112	      setMessages(data.messages ?? []);
113	    } catch {
114	      setError("Network error. Please try again.");
115	    } finally {
116	      setSending(false);
117	    }
118	  }
119	
120	  return (
121	    <div className="fixed bottom-4 right-4 z-[60] flex flex-col items-end gap-3">
122	      {open && (
123	        <div className="card glass flex h-[30rem] w-[22rem] max-w-[calc(100vw-2rem)] flex-col overflow-hidden p-0 shadow-2xl">
124	          {/* Header */}
125	          <div className="flex items-center justify-between border-b border-white/10 bg-gradient-to-r from-brand-500/20 to-accent-blue/20 px-4 py-3">
126	            <div>
127	              <p className="text-sm font-semibold text-slate-100">Chat with us</p>
128	              <p className="text-[11px] text-slate-400">We typically reply in a few minutes</p>
129	            </div>
130	            <button
131	              aria-label="Close chat"
132	              onClick={() => setOpen(false)}
133	              className="rounded-lg p-1 text-slate-400 hover:bg-white/10 hover:text-slate-200"
134	            >
135	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
136	                <path d="M18 6 6 18M6 6l12 12" />
137	              </svg>
138	            </button>
139	          </div>
140	
141	          {/* Transcript */}
142	          <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
143	            {messages.length === 0 && (
144	              <p className="mt-6 text-center text-sm text-slate-400">
145	                Hi there! 👋 How can we help you today?
146	              </p>
147	            )}
148	            {messages.map((m) => (
149	              <div
150	                key={m.id}
151	                className={`flex ${m.sender === "visitor" ? "justify-end" : "justify-start"}`}
152	              >
153	                <div
154	                  className={`max-w-[80%] whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
155	                    m.sender === "visitor"
156	                      ? "bg-brand-500 text-white"
157	                      : "border border-white/10 bg-white/[0.06] text-slate-200"
158	                  }`}
159	                >
160	                  {m.body}
161	                </div>
162	              </div>
163	            ))}
164	          </div>
165	
166	          {/* Composer */}
167	          <div className="border-t border-white/10 px-3 py-3">
168	            {!started && (
169	              <div className="mb-2 flex gap-2">
170	                <input
171	                  className="input py-1.5 text-xs"
172	                  placeholder="Your name (optional)"
173	                  value={name}
174	                  maxLength={120}
175	                  onChange={(e) => setName(e.target.value)}
176	                />
177	                <input
178	                  className="input py-1.5 text-xs"
179	                  placeholder="Email (optional)"
180	                  value={email}
181	                  maxLength={200}
182	                  onChange={(e) => setEmail(e.target.value)}
183	                />
184	              </div>
185	            )}
186	            {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
187	            <div className="flex items-end gap-2">
188	              <textarea
189	                className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
190	                placeholder="Type a message…"
191	                value={draft}
192	                maxLength={5000}
193	                rows={1}
194	                onChange={(e) => setDraft(e.target.value)}
195	                onKeyDown={(e) => {
196	                  if (e.key === "Enter" && !e.shiftKey) {
197	                    e.preventDefault();
198	                    send();
199	                  }
200	                }}
201	              />
202	              <button
203	                className="btn-primary shrink-0 px-3 py-2 text-sm"
204	                disabled={sending || !draft.trim()}
205	                onClick={send}
206	              >
207	                {sending ? "…" : "Send"}
208	              </button>
209	            </div>
210	          </div>
211	        </div>
212	      )}
213	
214	      {/* Floating bubble */}
215	      <button
216	        aria-label={open ? "Close chat" : "Open chat"}
217	        onClick={() => setOpen((o) => !o)}
218	        className="flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-brand-500 to-accent-blue text-white shadow-xl transition hover:scale-105"
219	      >
220	        {open ? (
221	          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
222	            <path d="M18 6 6 18M6 6l12 12" />
223	          </svg>
224	        ) : (
225	          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
226	            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
227	          </svg>
228	        )}
229	      </button>
230	    </div>
231	  );
232	}
