1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState, useTransition } from "react";
4	import {
5	  listConversations,
6	  replyToConversation,
7	  closeConversation,
8	  assignConversation,
9	} from "@/lib/actions-chat";
10	
11	/**
12	 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
13	 * first) and a thread view with a reply box. Polls `listConversations` every
14	 * few seconds so new visitor messages appear without a manual refresh.
15	 */
16	
17	type Msg = { id: string; sender: string; body: string; createdAt: string };
18	type Convo = {
19	  id: string;
20	  visitorId: string;
21	  userId: string | null;
22	  name: string | null;
23	  email: string | null;
24	  status: string;
25	  assignedToId: string | null;
26	  unreadForAgent: boolean;
27	  lastMessageAt: string;
28	  createdAt: string;
29	  messages: Msg[];
30	};
31	
32	const POLL_MS = 5000;
33	
34	function timeAgo(iso: string): string {
35	  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
36	  if (s < 60) return `${s}s ago`;
37	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
38	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
39	  return `${Math.floor(s / 86400)}d ago`;
40	}
41	
42	export default function ChatInbox({ initial }: { initial: Convo[] }) {
43	  const [convos, setConvos] = useState<Convo[]>(initial);
44	  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
45	  const [draft, setDraft] = useState("");
46	  const [error, setError] = useState("");
47	  const [pending, start] = useTransition();
48	  const scrollRef = useRef<HTMLDivElement>(null);
49	
50	  const refresh = useCallback(async () => {
51	    try {
52	      const rows = await listConversations();
53	      setConvos(rows);
54	    } catch {
55	      /* transient — next poll retries */
56	    }
57	  }, []);
58	
59	  useEffect(() => {
60	    const t = setInterval(refresh, POLL_MS);
61	    return () => clearInterval(t);
62	  }, [refresh]);
63	
64	  const selected = convos.find((c) => c.id === selectedId) ?? null;
65	
66	  useEffect(() => {
67	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
68	  }, [selected?.messages.length, selectedId]);
69	
70	  function doReply() {
71	    if (!selected || !draft.trim() || pending) return;
72	    const body = draft;
73	    setError("");
74	    start(async () => {
75	      const res = await replyToConversation(selected.id, body);
76	      if (res.error) {
77	        setError(res.error);
78	        return;
79	      }
80	      setDraft("");
81	      await refresh();
82	    });
83	  }
84	
85	  function doClose() {
86	    if (!selected) return;
87	    start(async () => {
88	      await closeConversation(selected.id);
89	      await refresh();
90	    });
91	  }
92	
93	  function doAssign() {
94	    if (!selected) return;
95	    start(async () => {
96	      await assignConversation(selected.id);
97	      await refresh();
98	    });
99	  }
100	
101	  function label(c: Convo): string {
102	    return c.name || c.email || `Visitor ${c.visitorId.slice(0, 8)}`;
103	  }
104	
105	  return (
106	    <div className="grid gap-4 lg:grid-cols-[20rem_1fr]">
107	      {/* Conversation list */}
108	      <div className="card max-h-[70vh] space-y-1 overflow-y-auto p-2">
109	        {convos.length === 0 && (
110	          <p className="p-4 text-center text-sm text-slate-500">No conversations yet.</p>
111	        )}
112	        {convos.map((c) => {
113	          const last = c.messages[c.messages.length - 1];
114	          const active = c.id === selectedId;
115	          return (
116	            <button
117	              key={c.id}
118	              onClick={() => setSelectedId(c.id)}
119	              className={`w-full rounded-xl border px-3 py-2.5 text-left transition ${
120	                active
121	                  ? "border-brand-500/50 bg-brand-500/10"
122	                  : "border-transparent hover:bg-white/[0.04]"
123	              }`}
124	            >
125	              <div className="flex items-center justify-between gap-2">
126	                <span className="truncate text-sm font-medium text-slate-100">
127	                  {label(c)}
128	                </span>
129	                <div className="flex shrink-0 items-center gap-1.5">
130	                  {c.unreadForAgent && (
131	                    <span className="h-2 w-2 rounded-full bg-amber-400" />
132	                  )}
133	                  {c.status === "CLOSED" && (
134	                    <span className="text-[10px] uppercase text-slate-500">closed</span>
135	                  )}
136	                </div>
137	              </div>
138	              <div className="mt-0.5 flex items-center justify-between gap-2">
139	                <span className="truncate text-xs text-slate-400">
140	                  {last ? (last.sender === "agent" ? "You: " : "") + last.body : "…"}
141	                </span>
142	                <span className="shrink-0 text-[10px] text-slate-500">
143	                  {timeAgo(c.lastMessageAt)}
144	                </span>
145	              </div>
146	            </button>
147	          );
148	        })}
149	      </div>
150	
151	      {/* Thread view */}
152	      <div className="card flex max-h-[70vh] flex-col p-0">
153	        {!selected ? (
154	          <div className="flex flex-1 items-center justify-center p-10 text-sm text-slate-500">
155	            Select a conversation to view it.
156	          </div>
157	        ) : (
158	          <>
159	            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-3">
160	              <div>
161	                <p className="text-sm font-semibold text-slate-100">{label(selected)}</p>
162	                <p className="text-xs text-slate-400">
163	                  {selected.email || "no email"}
164	                  {selected.userId ? " · registered customer" : " · guest"} ·{" "}
165	                  {selected.status.toLowerCase()}
166	                </p>
167	              </div>
168	              <div className="flex items-center gap-2">
169	                <button
170	                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
171	                  onClick={doAssign}
172	                  disabled={pending}
173	                >
174	                  Assign to me
175	                </button>
176	                {selected.status !== "CLOSED" && (
177	                  <button
178	                    className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
179	                    onClick={doClose}
180	                    disabled={pending}
181	                  >
182	                    Close
183	                  </button>
184	                )}
185	              </div>
186	            </div>
187	
188	            <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
189	              {selected.messages.map((m) => (
190	                <div
191	                  key={m.id}
192	                  className={`flex ${m.sender === "agent" ? "justify-end" : "justify-start"}`}
193	                >
194	                  <div
195	                    className={`max-w-[75%] whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
196	                      m.sender === "agent"
197	                        ? "bg-brand-500 text-white"
198	                        : "border border-white/10 bg-white/[0.06] text-slate-200"
199	                    }`}
200	                  >
201	                    {m.body}
202	                    <div
203	                      className={`mt-1 text-[10px] ${
204	                        m.sender === "agent" ? "text-white/60" : "text-slate-500"
205	                      }`}
206	                    >
207	                      {timeAgo(m.createdAt)}
208	                    </div>
209	                  </div>
210	                </div>
211	              ))}
212	            </div>
213	
214	            <div className="border-t border-white/10 px-4 py-3">
215	              {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
216	              <div className="flex items-end gap-2">
217	                <textarea
218	                  className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
219	                  placeholder="Type your reply…"
220	                  value={draft}
221	                  maxLength={5000}
222	                  rows={1}
223	                  onChange={(e) => setDraft(e.target.value)}
224	                  onKeyDown={(e) => {
225	                    if (e.key === "Enter" && !e.shiftKey) {
226	                      e.preventDefault();
227	                      doReply();
228	                    }
229	                  }}
230	                  disabled={pending}
231	                />
232	                <button
233	                  className="btn-primary shrink-0 px-4 py-2 text-sm"
234	                  onClick={doReply}
235	                  disabled={pending || !draft.trim()}
236	                >
237	                  {pending ? "…" : "Reply"}
238	                </button>
239	              </div>
240	            </div>
241	          </>
242	        )}
243	      </div>
244	    </div>
245	  );
246	}
