1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { realUser } from "./auth";
7	import { requireArea } from "./rbac";
8	
9	/**
10	 * Staff-side live-chat actions. Every export gates on `requireArea("support")`
11	 * so only support staff / admins can read or write conversations. This file is
12	 * a "use server" module, so it may export **async functions only**.
13	 */
14	
15	/** Shape returned to the admin inbox client component. */
16	type InboxMessage = { id: string; sender: string; body: string; createdAt: string };
17	type InboxConversation = {
18	  id: string;
19	  visitorId: string;
20	  userId: string | null;
21	  name: string | null;
22	  email: string | null;
23	  status: string;
24	  assignedToId: string | null;
25	  unreadForAgent: boolean;
26	  lastMessageAt: string;
27	  createdAt: string;
28	  messages: InboxMessage[];
29	};
30	
31	/** List conversations for the inbox, unread + newest first. Polled by the client. */
32	export async function listConversations(): Promise<InboxConversation[]> {
33	  await requireArea("support");
34	  const rows = await db.chatConversation.findMany({
35	    orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
36	    take: 200,
37	    include: { messages: { orderBy: { createdAt: "asc" } } },
38	  });
39	  return rows.map((c) => ({
40	    id: c.id,
41	    visitorId: c.visitorId,
42	    userId: c.userId,
43	    name: c.name,
44	    email: c.email,
45	    status: c.status,
46	    assignedToId: c.assignedToId,
47	    unreadForAgent: c.unreadForAgent,
48	    lastMessageAt: c.lastMessageAt.toISOString(),
49	    createdAt: c.createdAt.toISOString(),
50	    messages: c.messages.map((m) => ({
51	      id: m.id,
52	      sender: m.sender,
53	      body: m.body,
54	      createdAt: m.createdAt.toISOString(),
55	    })),
56	  }));
57	}
58	
59	/** Fetch a single conversation's messages (used when opening / polling a thread). */
60	export async function getConversation(id: string): Promise<InboxConversation | null> {
61	  await requireArea("support");
62	  if (typeof id !== "string" || !id) return null;
63	  const c = await db.chatConversation.findUnique({
64	    where: { id },
65	    include: { messages: { orderBy: { createdAt: "asc" } } },
66	  });
67	  if (!c) return null;
68	  return {
69	    id: c.id,
70	    visitorId: c.visitorId,
71	    userId: c.userId,
72	    name: c.name,
73	    email: c.email,
74	    status: c.status,
75	    assignedToId: c.assignedToId,
76	    unreadForAgent: c.unreadForAgent,
77	    lastMessageAt: c.lastMessageAt.toISOString(),
78	    createdAt: c.createdAt.toISOString(),
79	    messages: c.messages.map((m) => ({
80	      id: m.id,
81	      sender: m.sender,
82	      body: m.body,
83	      createdAt: m.createdAt.toISOString(),
84	    })),
85	  };
86	}
87	
88	/**
89	 * Staff reply: append an "agent" message, flag the thread unread for the user,
90	 * clear the agent-unread flag, and assign it to the replying staff member.
91	 */
92	export async function replyToConversation(
93	  id: string,
94	  body: string
95	): Promise<{ error?: string; ok?: boolean }> {
96	  const staff = await requireArea("support");
97	
98	  const parsed = z
99	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
100	    .safeParse({ id, body });
101	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
102	
103	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
104	  if (!convo) return { error: "Conversation not found." };
105	
106	  await db.$transaction([
107	    db.chatMessage.create({
108	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
109	    }),
110	    db.chatConversation.update({
111	      where: { id: parsed.data.id },
112	      data: {
113	        status: "OPEN",
114	        unreadForUser: true,
115	        unreadForAgent: false,
116	        assignedToId: staff.id,
117	        lastMessageAt: new Date(),
118	      },
119	    }),
120	  ]);
121	
122	  // If the visitor is a signed-in customer, drop them a notification.
123	  if (convo.userId) {
124	    await db.notification
125	      .create({
126	        data: {
127	          userId: convo.userId,
128	          title: "New reply in your live chat",
129	          href: "/dashboard",
130	        },
131	      })
132	      .catch(() => {});
133	  }
134	
135	  revalidatePath("/admin/chat");
136	  return { ok: true };
137	}
138	
139	/** Close a conversation (staff). */
140	export async function closeConversation(
141	  id: string
142	): Promise<{ error?: string; ok?: boolean }> {
143	  await requireArea("support");
