model ChatMessage {
  id             String           @id @default(cuid())
  conversationId String
  conversation   ChatConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender         String           // "visitor" | "agent"
  body           String           // may be "" for an image-only message
  createdAt      DateTime         @default(now())
  attachment     ChatAttachment?

  @@index([conversationId, createdAt])
}

/// An image attached to a single chat message. Bytes live in Postgres (not the
/// filesystem) so the non-root web process — which can only write .next — never
/// needs write access to disk. `mime` is the signature-verified type (only
/// image/png|jpeg|gif|webp are ever stored; see lib/chat-attachment.ts).
model ChatAttachment {
  id        String      @id @default(cuid())
  messageId String      @unique
  message   ChatMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)
  mime      String
  sizeBytes Int
  data      Bytes
  createdAt DateTime    @default(now())
}

