 * Staff reply carrying an image attachment. Same authorization and side effects
 * as `replyToConversation` (requireArea("support"), notify, assign, unread) but
 * the message body may be empty and it stores a signature-verified image in
 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
 * rejection) run in `validateImageBytes` — the client cannot bypass them.
 */
export async function replyWithAttachment(
  formData: FormData
): Promise<{ error?: string; ok?: boolean }> {
  const staff = await requireArea("support");

  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) return { error: "Too many uploads. Please slow down." };

  const id = formData.get("conversationId");
  const rawBody = formData.get("body");
  const file = formData.get("file");

  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
  if (!(file instanceof File)) return { error: "No image provided." };
  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };

  const convo = await db.chatConversation.findUnique({ where: { id } });
  if (!convo) return { error: "Conversation not found." };

  const bytes = Buffer.from(await file.arrayBuffer());
  const check = validateImageBytes(bytes, file.type);
  if (!check.ok) return { error: check.error };

  await db.$transaction(async (tx) => {
    const msg = await tx.chatMessage.create({
      data: { conversationId: id, sender: "agent", body },
    });
    await tx.chatAttachment.create({
      data: {
        messageId: msg.id,
        mime: check.mime,
        sizeBytes: check.bytes.length,
        data: check.bytes,
      },
    });
