import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";

export const runtime = "nodejs";

/**
 * Image upload for <ChatWidget/>.
 *
 * POST /api/chat/upload  (multipart/form-data: visitorId, file, optional body,
 * optional name/email) — attaches an image to the visitor's OPEN conversation
 * (created if none), exactly like POST /api/chat but carrying an image.
 *
 * Authorization mirrors POST /api/chat: the conversation is scoped strictly by
 * the client-supplied `visitorId`, so a visitor can only ever attach to their
 * own thread. The image is validated by signature (not the client-declared
 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
 * Postgres. Per-IP rate limited.
 */

function clientIp(req: Request): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || "unknown";
}

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat-upload:${clientIp(req)}`, { max: 15, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many uploads. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
  }

  const visitorId = clip(form.get("visitorId"), 100);
  const body = clip(form.get("body"), 5000) ?? "";
  const name = clip(form.get("name"), 120);
  const email = clip(form.get("email"), 200);
  const file = form.get("file");

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
  // Cheap guard before buffering the whole body into memory.
  if (file.size > MAX_ATTACHMENT_BYTES) {
    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
  }

  const bytes = Buffer.from(await file.arrayBuffer());
  const check = validateImageBytes(bytes, file.type);
  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });

  const user = await currentUser();

  // Continue the visitor's existing open conversation, else start a new one.
  let convo = await db.chatConversation.findFirst({
    where: { visitorId, status: "OPEN" },
    orderBy: { lastMessageAt: "desc" },
    select: { id: true, name: true, email: true },
  });

  if (!convo) {
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  const convoId = convo.id;
  await db.$transaction(async (tx) => {
    const msg = await tx.chatMessage.create({
      data: { conversationId: convoId, sender: "visitor", body },
    });
    await tx.chatAttachment.create({
      data: {
        messageId: msg.id,
        mime: check.mime,
        sizeBytes: check.bytes.length,
        data: check.bytes,
      },
    });
    await tx.chatConversation.update({
      where: { id: convoId },
      data: {
        unreadForAgent: true,
        lastMessageAt: new Date(),
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo!.name ? { name } : {}),
        ...(email && !convo!.email ? { email } : {}),
      },
    });
  });

  const full = await db.chatConversation.findUnique({
    where: { id: convoId },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });

  return NextResponse.json({
    conversation: full
      ? { id: full.id, status: full.status, name: full.name, email: full.email }
      : null,
    messages: (full?.messages ?? []).map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
      attachment: m.attachment
        ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
        : null,
    })),
  });
}

import { db } from "@/lib/db";
import { realUser, currentUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { isAllowedImageMime } from "@/lib/chat-attachment";

export const runtime = "nodejs";

/**
 * GET /api/chat/attachment/[id]?visitorId=…  — stream a chat image ONLY to an
 * authorized viewer:
 *   • any staff member (SUPPORT / ADMIN), OR
 *   • the visitor who owns the conversation (visitorId query param matches), OR
 *   • the signed-in customer the conversation is linked to (userId matches).
 *
 * `id` is a database id, never a filename, so there is no path traversal. The
 * response is locked down: the real stored MIME (always an allow-listed image),
 * `nosniff`, an inline disposition with a fixed filename, and a `default-src
 * 'none'` CSP so it can never execute as a document even if a browser is coaxed
 * into treating it as one.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });

  const attachment = await db.chatAttachment.findUnique({
    where: { id },
    include: { message: { include: { conversation: true } } },
  });
  if (!attachment) return new Response("Not found", { status: 404 });

  const convo = attachment.message.conversation;

  // --- Authorization: same model as upload (participant or staff) ---
  let authorized = false;

  const staff = await realUser();
  if (staff && isStaff(staff.role)) {
    authorized = true;
  } else {
    const url = new URL(req.url);
    const visitorId = clip(url.searchParams.get("visitorId"), 100);
    if (visitorId && visitorId === convo.visitorId) {
      authorized = true;
    } else if (convo.userId) {
      const user = await currentUser();
      if (user && user.id === convo.userId) authorized = true;
    }
  }

  if (!authorized) return new Response("Forbidden", { status: 403 });

  // Defense in depth: never serve anything that isn't an allow-listed image.
  const mime = isAllowedImageMime(attachment.mime) ? attachment.mime : "application/octet-stream";

  const data: Buffer = Buffer.isBuffer(attachment.data)
    ? attachment.data
    : Buffer.from(attachment.data as Uint8Array);

  return new Response(new Uint8Array(data), {
    status: 200,
    headers: {
      "Content-Type": mime,
      "Content-Length": String(data.length),
      "Content-Disposition": 'inline; filename="image"',
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
      "Cache-Control": "private, max-age=86400, no-transform",
    },
  });
}

