  assignConversation,
} from "@/lib/actions-chat";

type Attachment = { id: string; mime: string; sizeBytes: number };
type Msg = {
  id: string;
  sender: string;
  body: string;
  createdAt: string;
  attachment?: Attachment | null;
};
type Convo = {

const POLL_MS = 5000;

// Client-side pre-checks only; replyWithAttachment re-validates by signature.
const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

function imageError(file: File): string | null {
  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
  return null;
}

