function doReply() {
  if (!selected || pending) return;
  if (!draft.trim() && !pendingImage) return;
  const body = draft;
  setError("");

  if (pendingImage) {
    const fd = new FormData();
    fd.append("conversationId", selected.id);
    fd.append("file", pendingImage.file);
    if (body.trim()) fd.append("body", body.trim());
    start(async () => {
      const res = await replyWithAttachment(fd);
      if (res.error) {
        setError(res.error);
        return;
      }
      setDraft("");
      clearImage();
      await refresh();
    });
    return;
  }

  start(async () => {
    const res = await replyToConversation(selected.id, body);
    if (res.error) {
      setError(res.error);
      return;
    }
    setDraft("");
    await refresh();
  });
}

